import { ApiProperty, ApiPropertyOptional } from "@nestjs/swagger";
import { CourseType, SimulatedOutcome } from "../generated/prisma/enums";
import {
  IsBoolean,
  IsDateString,
  IsIn,
  IsInt,
  IsOptional,
  IsString,
  IsEmail,
  IsUUID,
  IsUrl,
  Max,
  MaxLength,
  Min,
  MinLength,
  ValidateIf,
} from "class-validator";
// Allowed values come from the database enums generated by Prisma.
export const provisioningOutcomes = Object.values(SimulatedOutcome);
export type ProvisioningOutcome = SimulatedOutcome;
const courseTypes = Object.values(CourseType);
export class RegistrationDto {
  @ApiProperty() @IsUUID() offeringId!: string;
}
export class DecisionDto {
  @ApiProperty({ enum: ["approved", "declined"] })
  @IsIn(["approved", "declined"])
  decision!: "approved" | "declined";
}
export class OfferingDto {
  @ApiProperty() @IsString() @MinLength(3) @MaxLength(120) title!: string;
  @ApiProperty({ enum: ["Technology", "Leadership", "Healthcare", "Ministry"] })
  @IsIn(["Technology", "Leadership", "Healthcare", "Ministry"])
  category!: string;
  @ApiProperty() @IsString() @MinLength(10) @MaxLength(240) summary!: string;
  @ApiProperty()
  @IsString()
  @MinLength(20)
  @MaxLength(4000)
  description!: string;
  @ApiProperty() @IsString() @MinLength(3) @MaxLength(100) format!: string;
  @ApiProperty({ enum: courseTypes })
  @IsIn(courseTypes)
  courseType!: CourseType;
  @ApiPropertyOptional({
    description: "Required for cohort courses; omit for self-paced courses.",
  })
  @ValidateIf((o) => o.courseType === "cohort" || o.startDate != null)
  @IsDateString({ strict: true })
  startDate?: string;
  @ApiPropertyOptional({
    description: "Required for cohort courses; omit for self-paced courses.",
  })
  @ValidateIf((o) => o.courseType === "cohort" || o.endDate != null)
  @IsDateString({ strict: true })
  endDate?: string;
  @ApiProperty() @IsInt() @Min(1) @Max(10000) capacity!: number;
  @ApiProperty() @IsInt() @Min(0) @Max(1000000) priceCents!: number;
  @ApiProperty() @IsBoolean() approvalRequired!: boolean;
  @ApiPropertyOptional({
    default: 7,
    description:
      "Days an approval stays valid before the learner must reserve.",
  })
  @IsOptional()
  @IsInt()
  @Min(1)
  @Max(365)
  approvalValidDays?: number;
  @ApiPropertyOptional({
    default: 7,
    description:
      "Scheduled courses: days after the start date when enrollment closes.",
  })
  @IsOptional()
  @IsInt()
  @Min(0)
  @Max(365)
  enrollmentCloseDays?: number;
  @ApiPropertyOptional({
    description: "HTTPS link to the mapped Canvas course.",
  })
  @IsOptional()
  @IsUrl({ protocols: ["https"], require_protocol: true })
  @MaxLength(500)
  canvasCourseUrl?: string;
}
export class OfferingSettingsDto {
  @ApiProperty() @IsInt() @Min(1) version!: number;
  @ApiProperty({ minimum: 1, maximum: 365 })
  @IsInt()
  @Min(1)
  @Max(365)
  approvalValidDays!: number;
  @ApiProperty({ minimum: 0, maximum: 365 })
  @IsInt()
  @Min(0)
  @Max(365)
  enrollmentCloseDays!: number;
  @ApiPropertyOptional({
    nullable: true,
    description: "HTTPS link to the mapped Canvas course; null removes it.",
  })
  @IsOptional()
  @IsUrl({ protocols: ["https"], require_protocol: true })
  @MaxLength(500)
  canvasCourseUrl?: string | null;
}
export class PublishDto {
  @ApiProperty() @IsInt() @Min(1) version!: number;
}
export class QueryDto {
  @ApiPropertyOptional()
  @IsOptional()
  @IsString()
  @MaxLength(120)
  search?: string;
  @ApiPropertyOptional({
    enum: ["Technology", "Leadership", "Healthcare", "Ministry"],
  })
  @IsOptional()
  @IsIn(["Technology", "Leadership", "Healthcare", "Ministry"])
  category?: string;
}

export class DemoUserDto {
  @ApiProperty({
    example: "learner@example.com",
    description: "Mock sign-in only; no password accepted.",
  })
  @IsEmail()
  @MaxLength(254)
  email!: string;
}
export class SimulationDto {
  @ApiProperty({
    enum: provisioningOutcomes,
    description:
      "PROTOTYPE ONLY: outcome applied to provisioning queued after this change.",
  })
  @IsIn(provisioningOutcomes)
  provisioningOutcome!: ProvisioningOutcome;
}
export class ExceptionActionDto {
  @ApiProperty({
    description: "Why staff are taking this action; recorded in the audit log.",
    minLength: 10,
    maxLength: 500,
  })
  @IsString()
  @MinLength(10)
  @MaxLength(500)
  reason!: string;
}
export class OfferingEditDto extends OfferingDto {
  @ApiProperty({ description: "Current version, for conflict detection." })
  @IsInt()
  @Min(1)
  version!: number;
  @ApiPropertyOptional({
    description:
      "Required (10–500 characters) when the offering is published; recorded in the audit log.",
  })
  @IsOptional()
  @IsString()
  @MaxLength(500)
  reason?: string;
}
export class UnpublishDto {
  @ApiProperty() @IsInt() @Min(1) version!: number;
  @ApiProperty({ minLength: 10, maxLength: 500 })
  @IsString()
  @MinLength(10)
  @MaxLength(500)
  reason!: string;
}
